from pathlib import Path
p=Path('qa/user-flow.spec.mjs')
s=p.read_text()
old="""  const inputs=page.locator('.field input');await inputs.nth(0).fill('QA JurisQuest');await inputs.nth(1).fill(email);await inputs.nth(2).fill(password);await inputs.nth(3).fill(password);await page.getByRole('button',{name:/Criar conta/i}).click();await page.waitForTimeout(1200);\n  if(!page.url().includes('/dashboard')){await page.goto(BASE,{waitUntil:'networkidle'});await page.locator('input[name=email]').fill(email);await page.locator('input[name=password]').fill(password);await page.getByRole('button',{name:/Entrar no JurisQuest/i}).click()}\n  await page.waitForURL(/dashboard/,{timeout:30000});log('Cadastro e login reais',true);await shot(page,'01-dashboard');"""
new="""  const inputs=page.locator('.field input');await inputs.nth(0).fill('QA JurisQuest');await inputs.nth(1).fill(email);await inputs.nth(2).fill(password);await inputs.nth(3).fill(password);await page.getByRole('button',{name:/Criar conta/i}).click();\n  try{await page.waitForURL(/dashboard/,{timeout:6500})}catch{}\n  if(!page.url().includes('/dashboard')){await page.goto(BASE,{waitUntil:'networkidle'});for(let attempt=0;attempt<4&&!page.url().includes('/dashboard');attempt++){await page.locator('input[name=email]').fill(email);await page.locator('input[name=password]').fill(password);await page.getByRole('button',{name:/Entrar no JurisQuest/i}).click();try{await page.waitForURL(/dashboard/,{timeout:4500})}catch{if(attempt<3){await page.waitForTimeout(300*(attempt+1));await page.goto(BASE,{waitUntil:'networkidle'})}}}}\n  await page.waitForURL(/dashboard/,{timeout:5000});log('Cadastro e login reais',true);await shot(page,'01-dashboard');"""
if old not in s: raise RuntimeError('signup QA anchor missing')
p.write_text(s.replace(old,new,1))
